// resposta paginada do node HTTP Request chega como 1 item por PÁGINA
// (cada item.json = array daquela página, quando a paginação nativa
// está ativa), ou já achatada em N items — cobre os dois casos e
// concatena tudo num array único, igual buscarTudo() do backfill.
const TENANT_ID = $('Para cada tenant ativo').first().json.tenant_id;
const brutos = $input.all().map((i) => i.json);
let linhas = [];
for (const b of brutos) {
  if (Array.isArray(b)) linhas = linhas.concat(b);
  else if (b && Object.keys(b).length > 0) linhas.push(b); // ignora item fake do Always Output Data quando a API vem vazia
}

function pgVal(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  if (typeof v === 'object') return `'${JSON.stringify(v).replace(/'/g, "''")}'::jsonb`;
  return `'${String(v).replace(/'/g, "''")}'`;
}

// Mesmo mapeamento de sincronizarProdutos() em backfill_periodo.js:
// ProdutoIntegracaoDto não tem "marca" -- nomeLaboratorio é a
// aproximação (fabricante); categoria = nomeCategoria (tipo de uso),
// grupo = nomeGrupo (categoria de produto de verdade) -- campos
// separados de propósito (achado 01/08/2026).
const COLUNAS = [
  'tenant_id', 'codigo', 'codigo_barras', 'nome', 'categoria', 'grupo', 'marca',
  'preco_venda', 'custo_medio', 'estoque_atual', 'tipo_lista',
];
const ATUALIZAR = COLUNAS.slice(2).map((c) => `${c} = EXCLUDED.${c}`).join(', ');
const TAMANHO_LOTE = 500;

const saida = [];
for (let inicio = 0; inicio < linhas.length; inicio += TAMANHO_LOTE) {
  const lote = linhas.slice(inicio, inicio + TAMANHO_LOTE);
  const grupos = lote.map((p) => {
    const valores = [
      TENANT_ID,
      p.codigo,
      p.codigoBarras != null ? String(p.codigoBarras) : null,
      p.nome,
      p.nomeCategoria ?? null,
      p.nomeGrupo ?? null,
      p.nomeLaboratorio ?? null,
      p.valorVenda ?? 0,
      p.valorCustoMedio ?? p.valorCusto ?? 0,
      p.quantidadeEstoque ?? 0,
      p.tipoLista ?? null,
    ];
    return `(${valores.map(pgVal).join(', ')})`;
  });
  const sql = `INSERT INTO produto_catalogo (${COLUNAS.join(', ')})
VALUES ${grupos.join(',\n')}
ON CONFLICT (tenant_id, codigo) DO UPDATE SET ${ATUALIZAR};`;
  saida.push({ json: { sql, tipo: 'lote', quantidade: lote.length } });
}

if (linhas.length === 0) {
  saida.push({ json: { sql: 'SELECT 1', tipo: 'vazio', quantidade: 0 } });
}

// Última linha: atualiza sync_control (upsert -- 'produto' pode nunca
// ter tido linha aqui, já que era fora do escopo do incremental).
saida.push({
  json: {
    sql: `INSERT INTO sync_control (tenant_id, entity_name, last_synced_at) VALUES ('${TENANT_ID}', 'produto', now())
ON CONFLICT (tenant_id, entity_name) DO UPDATE SET last_synced_at = now();`,
    tipo: 'sync_control',
    quantidade: linhas.length,
  },
});

return saida;

